import sys
sys.setrecursionlimit(200000)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        V = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(V)]

    try:
        while True:
            u_str = next(iterator)
            v_str = next(iterator)
            u = int(u_str)
            v = int(v_str)
            adj[u].append(v)
            adj[v].append(u)
    except StopIteration:
        pass

    disc = [-1] * V
    low = [-1] * V
    parent = [-1] * V
    timer = [0]
    bridges = []

    def dfs(u):
        disc[u] = low[u] = timer[0]
        timer[0] += 1

        for v in adj[u]:
            if disc[v] == -1:
                parent[v] = u
                dfs(v)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    if u < v:
                        bridges.append([u, v])
                    else:
                        bridges.append([v, u])
            elif v != parent[u]:
                low[u] = min(low[u], disc[v])

    for i in range(V):
        if disc[i] == -1:
            dfs(i)

    bridges.sort()

    for bridge in bridges:
        print(f"{bridge[0]} {bridge[1]}")

if __name__ == "__main__":
    main()
